design_text:
{
  "site_summary": "A damp north-facing balcony with high moisture and dripping pipes, perfectly safe for a curious cat.",
  "layout_strategy": "The scheme is structured with trailing shade-loving plants hanging from the wall hooks at vertical level, lush upright ferns and textured foliage in containers at mid-height against the wall, and a dedicated pet-safe turf tray at ground level for the cat to safely sit and nibble.",
  "combination_logic": "The combination relies on contrasting dark glossy fronds, delicate feathery foliage, and soft sprawling grasses. The eye moves from the vertical trailing greenery down to the architectural mid-height containers and rests on the accessible soft ground layer. It offers year-round evergreen texture suited to gloomy, wet conditions.",
  "zones": [
    {
      "zone_name": "Railing Cascade",
      "zone_role": "screening",
      "layer": "vertical",
      "placement": "On wall-mounted hooks above the balcony, north-facing, in deep shade and receiving constant ambient moisture.",
      "plants": [
        {
          "scientific_name": "Saxifraga stolonifera",
          "common_name": "Strawberry Begonia",
          "why": "Thrives in deep shade and wet conditions, sending out beautiful creeping red stolons that trail down.",
          "role_in_combination": "Provides fine-textured trailing lines and reddish underside leaf contrast that soften the container edges."
        }
      ],
      "maintenance": [
        "Water moderately even though the site is damp, checking that drainage holes are clear.",
        "Feed with half-strength liquid fertilizer monthly in spring and summer.",
        "Prune dead or yellowing leaves in autumn."
      ]
    },
    {
      "zone_name": "Shade Wall Oasis",
      "zone_role": "focal",
      "layer": "mid",
      "placement": "Against the back wall on plant stands at knee-to-waist height, north-facing, protected from wind but exposed to drip zone moisture.",
      "plants": [
        {
          "scientific_name": "Polystichum munitum",
          "common_name": "Western Sword Fern",
          "why": "A robust, moisture-loving shade fern that handles damp conditions brilliantly.",
          "role_in_combination": "Delivers strong vertical height and glossy, sword-shaped fronds that contrast with delicate foliage."
        },
        {
          "scientific_name": "Acorus gramineus",
          "common_name": "Grassy-leaved Sweet Flag",
          "why": "Loves wet soil and adds a completely different blade-like texture.",
          "role_in_combination": "Brings grassy vertical accents that weave visually between the broader fronds of the fern."
        }
      ],
      "maintenance": [
        "Water weekly during drier spells, though the dripping pipes will handle most moisture needs.",
        "Remove old tattered fronds in early spring to make way for new fiddleheads.",
        "Repot every two years into a heavier, moisture-retentive potting mix."
      ]
    },
    {
      "zone_name": "Feline Lounge",
      "zone_role": "grazing",
      "layer": "ground",
      "placement": "On the balcony floor in a wide, shallow tray, north-facing, fully accessible to the cat for sitting and nibbling.",
      "plants": [
        {
          "scientific_name": "Dactylis glomerata",
          "common_name": "Cat Grass",
          "why": "Completely non-toxic, safe for feline digestion, and enjoys damp conditions.",
          "role_in_combination": "Provides a soft, walkable, and chewable ground-level texture that invites the cat to interact with the garden safely."
        }
      ],
      "maintenance": [
        "Check daily that the soil is not becoming waterlogged and stagnant.",
        "Re-sow fresh cat grass seeds every 4 to 6 weeks to keep the grazing patch lush and appealing.",
        "Trim the grass back if it gets too leggy."
      ]
    }
  ],
  "care_instructions": [
    {
      "task": "Clear accumulated debris and fallen leaves from the balcony floor and pot drainage holes to prevent anaerobic rot from dripping water.",
      "frequency": "Weekly",
      "season": "Autumn and Winter"
    },
    {
      "task": "Apply a balanced liquid houseplant fertilizer to the mid-layer containers to compensate for nutrients leaching out from constant dampness.",
      "frequency": "Monthly",
      "season": "Spring and Summer"
    },
    {
      "task": "Check the cat grass tray for mold growth due to the high ambient moisture and replace the soil and seed mix if necessary.",
      "frequency": "Every four weeks",
      "season": "All seasons"
    }
  ],
  "care_cautions": [
    "Root rot in the mid-layer containers due to the combination of dripping pipes and lack of direct sun drying out the potting mix.",
    "Mold and fungal growth in the Feline Lounge ground tray caused by persistent high moisture and poor air circulation in the shade.",
    "The cat digging up and spilling the wet soil in the low-lying containers if they are not adequately weighted or covered with protective wire grids."
  ],
  "pet_safety_note": "Every plant included in this scheme is completely non-toxic and safe for cats, and the ground-level zone is specifically designed for your cat to safely sit in and graze."
}
